{
  "objectives": [
    {
      "level": "primary",
      "text": "Estimate the ORR for metastatic BCC (Group 1) or unresectable locally advanced BCC (Group 2), according to central review, when treated with cemiplimab monotherapy in patients who have progressed on HHI therapy, or were intolerant of prior HHI therapy.",
      "quote": "The primary objective of the study is to estimate the ORR for metastatic BCC (Group 1) or unresectable locally advanced BCC (Group 2), according to central review, when treated with cemiplimab monotherapy in patients who have progressed on HHI therapy, or were intolerant of prior HHI therapy.",
      "endpoints": [
        {
          "text": "ORR as determined by central review",
          "measure": "ORR",
          "timepoints_weeks": [],
          "quote": "The primary efficacy endpoint for this study is the ORR as determined by central review."
        }
      ]
    },
    {
      "level": "secondary",
      "text": "Estimate ORR according to investigator review; estimate duration of response, PFS by central and investigator review, and OS; estimate CR rate by central review; assess safety and tolerability; assess PK; assess immunogenicity; assess impact on quality of life using EORTC QLQ-C30 and Skindex-16.",
      "quote": "The secondary objectives for both Group 1 and Group 2 are to: • Estimate ORR (see Appendix 1 and Appendix 2) according to investigator review • Estimate the duration of response, progression-free survival (PFS) by central and investigator review, and overall survival (OS) • Estimate the complete response (CR) rate by central review • Assess the safety and tolerability of cemiplimab • Assess the pharmacokinetics (PK) of cemiplimab (at select sites only) • Assess the immunogenicity of cemiplimab • Assess the impact of cemiplimab on quality of life using European Organisation for Research and Treatment of Cancer Quality of Life Questionnaire Core 30 (EORTC QLQ-C30) and Skindex-16",
      "endpoints": [
        {
          "text": "ORR according to investigator review",
          "measure": "ORR",
          "timepoints_weeks": [],
          "quote": "Estimate ORR (see Appendix 1 and Appendix 2) according to investigator review"
        },
        {
          "text": "Duration of response",
          "measure": "Duration of response",
          "timepoints_weeks": [],
          "quote": "Estimate the duration of response, progression-free survival (PFS) by central and investigator review, and overall survival (OS)"
        },
        {
          "text": "Progression-free survival (PFS) by central and investigator review",
          "measure": "PFS",
          "timepoints_weeks": [],
          "quote": "Estimate the duration of response, progression-free survival (PFS) by central and investigator review, and overall survival (OS)"
        },
        {
          "text": "Overall survival (OS)",
          "measure": "OS",
          "timepoints_weeks": [],
          "quote": "Estimate the duration of response, progression-free survival (PFS) by central and investigator review, and overall survival (OS)"
        },
        {
          "text": "Complete response (CR) rate by central review",
          "measure": "CR rate",
          "timepoints_weeks": [],
          "quote": "Estimate the complete response (CR) rate by central review"
        },
        {
          "text": "Safety and tolerability of cemiplimab",
          "measure": "AEs",
          "timepoints_weeks": [],
          "quote": "Assess the safety and tolerability of cemiplimab"
        },
        {
          "text": "Pharmacokinetics (PK) of cemiplimab (at select sites only)",
          "measure": "Concentrations of cemiplimab in serum",
          "timepoints_weeks": [],
          "quote": "Assess the pharmacokinetics (PK) of cemiplimab (at select sites only)"
        },
        {
          "text": "Immunogenicity of cemiplimab",
          "measure": "Anti-cemiplimab antibodies",
          "timepoints_weeks": [],
          "quote": "Assess the immunogenicity of cemiplimab"
        },
        {
          "text": "Impact of cemiplimab on quality of life using EORTC QLQ-C30 and Skindex-16",
          "measure": "Change in scores of patient-reported outcomes in the EORTC QLQ-C30 and the Skindex-16",
          "timepoints_weeks": [],
          "quote": "Assess the impact of cemiplimab on quality of life using European Organisation for Research and Treatment of Cancer Quality of Life Questionnaire Core 30 (EORTC QLQ-C30) and Skindex-16"
        }
      ]
    },
    {
      "level": "exploratory",
      "text": "Explore pharmacodynamic effects of cemiplimab in tumor biopsies obtained at baseline, during treatment, and at progression in BCC patients treated with cemiplimab, and assess predictive potential and correlation to clinical response for biomarkers of interest including tumor RNA expression, TILs, expression levels of PD-L1, GITR, LAG-3, mutations in oncogenes and neoantigens, and tumor mutational burden.",
      "quote": "The exploratory objectives (for Group 2 only) are to explore the pharmacodynamic effects of cemiplimab in tumor biopsies obtained at baseline, during treatment, and at progression in BCC patients treated with cemiplimab, and to assess predictive potential and correlation to clinical response for biomarkers of interest including but not limited to: • Tumor RNA expression • Number and distribution of tumor-infiltrating lymphocytes (TILs) (CD8+ T cells, CD4+ T cells, T regulatory cells, and tissue permitting, other subtypes such as B cells, myeloid-derived cells, natural killer [NK] cells, etc.) • Expression levels (mRNA and/or protein) of programmed death ligand 1(PD-L1), glucocorticoid-induced TNFR family related gene (GITR), and lymphocyte activation gene-3 (LAG-3), and possibly other check-point modulators • Mutations in known oncogenes and potential tumor neoantigens • Tumor mutational burden",
      "endpoints": [
        {
          "text": "Associations between tumor non-synonymous mutational burden at baseline and efficacy of cemiplimab",
          "measure": "Tumor mutational burden",
          "timepoints_weeks": [],
          "quote": "Associations between tumor non-synonymous mutational burden at baseline and efficacy of cemiplimab"
        },
        {
          "text": "Pharmacodynamic changes in tumor mRNA expression",
          "measure": "Changes in tumor mRNA expression",
          "timepoints_weeks": [],
          "quote": "Changes in tumor mRNA expression"
        },
        {
          "text": "Changes in number of TILs and distribution",
          "measure": "Number and distribution of TILs",
          "timepoints_weeks": [],
          "quote": "Changes in number of TILs (CD8+ T cells, CD4+ T cells, T regulatory cells, and tissue permitting, other subtypes such as B cells, myeloid-derived cells, NK cells, etc.) and descriptive change in distribution of TILs in respect to tumor tissue and stroma"
        },
        {
          "text": "Change in expression levels of PD-L1, GITR, LAG-3, and other check-point modulators",
          "measure": "Expression levels (mRNA and/or protein) of PD-L1, GITR, LAG-3",
          "timepoints_weeks": [],
          "quote": "Change in expression levels (mRNA and/or protein) of PD-L1, GITR, and LAG-3, and possibly other check-point modulators"
        },
        {
          "text": "Change in number and type of genetic mutations in known oncogenes and potential tumor neoantigens",
          "measure": "Mutations in known oncogenes and potential tumor neoantigens",
